import { useEffect, useState } from "react";
import { getForecast } from "../services/api";

function Weather({
  cities,
  activeCity,
  selectedCity,
  onSelect,
  onAdd,
  onRemove,
  onRefresh,
}) {
  const [forecast, setForecast] = useState(null);
  const [forecastError, setForecastError] = useState("");
  const [weekly, setWeekly] = useState(false);

  useEffect(() => {
    if (!selectedCity) {
      setForecast(null);
      return;
    }

    let cancelled = false;
    setForecast(null);
    setForecastError("");

    getForecast(selectedCity)
      .then((data) => {
        if (!cancelled) setForecast(data);
      })
      .catch(() => {
        if (!cancelled) {
          setForecastError("Не вдалося завантажити прогноз.");
        }
      });

    return () => {
      cancelled = true;
    };
  }, [selectedCity]);

  const items = forecast?.list || [];
  const hours = items.slice(0, 8);

  // OpenWeatherMap безкоштовно повертає прогноз кожні 3 години
  const days = Object.values(
    items.reduce((result, item) => {
      const date = item.dt_txt.split(" ")[0];

      if (!result[date]) result[date] = item;

      return result;
    }, {})
  ).slice(0, 7);

  const chartPoints = hours
    .map((item, index) => {
      const x = hours.length > 1
        ? (index / (hours.length - 1)) * 100
        : 50;
      const y = 100 - ((item.main.temp + 10) / 50) * 100;

      return `${x},${Math.max(5, Math.min(95, y))}`;
    })
    .join(" ");

  return (
    <section className="section weather-section" id="weather">
      <div className="section-heading">
        <div>
          <span className="eyebrow">ПОГОДА ЗАРАЗ</span>
          <h2>Твої міста</h2>
        </div>
        <span className="city-count">{cities.length} міст</span>
      </div>

      {cities.length === 0 ? (
        <div className="empty-state">
          <span>🌤️</span>
          <h3>Почнемо з твого міста?</h3>
          <p>Введи назву в пошуку вище, щоб побачити погоду.</p>
        </div>
      ) : (
        <div className="weather-grid">
          {cities.map((city) => (
            <article
              key={city.id}
              className={`weather-card ${
                selectedCity === city.name ? "selected" : ""
              }`}
            >
              <button
                className="card-main"
                onClick={() => onSelect(city.name)}
              >
                <span className="card-location">
                  {city.name}, {city.country}
                </span>
                <img
                  src={`https://openweathermap.org/img/wn/${city.icon}@2x.png`}
                  alt={city.description}
                />
                <span className="card-temp">{city.temp}°</span>
                <span className="card-description">
                  {city.description}
                </span>
                <span className="card-feels">
                  Відчувається як {city.feels}°
                </span>
              </button>

              <div className="card-actions">
                <button onClick={() => onRefresh(city.name)}>
                  ↻ Оновити
                </button>
                <button
                  onClick={() => onRemove(city.name)}
                  aria-label={`Видалити ${city.name}`}
                >
                  Видалити
                </button>
              </div>
            </article>
          ))}
        </div>
      )}

      {activeCity && (
        <div className="details-panel">
          <div className="details-heading">
            <div>
              <span className="eyebrow">ДЕТАЛЬНИЙ ПРОГНОЗ</span>
              <h2>
                {activeCity.name}, {activeCity.country}
              </h2>
            </div>

            <button
              className="outline-button"
              onClick={() => onRefresh(activeCity.name)}
            >
              ↻ Оновити погоду
            </button>
          </div>

          <div className="details-grid">
            <div className="current-weather">
              <img
                src={`https://openweathermap.org/img/wn/${activeCity.icon}@4x.png`}
                alt={activeCity.description}
              />
              <div className="big-temp">{activeCity.temp}°</div>
              <p>{activeCity.description}</p>
              <span>Відчувається як {activeCity.feels}°</span>
            </div>

            <div className="weather-stats">
              <div className="stat">
                <span>💧 Вологість</span>
                <strong>{activeCity.humidity}%</strong>
              </div>
              <div className="stat">
                <span>💨 Вітер</span>
                <strong>{activeCity.wind} м/с</strong>
              </div>
              <div className="stat">
                <span>🌡️ Тиск</span>
                <strong>{activeCity.pressure} гПа</strong>
              </div>
              <div className="stat">
                <span>🌡️ Відчувається</span>
                <strong>{activeCity.feels}°C</strong>
              </div>
            </div>
          </div>

          <div className="forecast-heading">
            <h3>Температура протягом дня</h3>
            <span>Наступні 24 години</span>
          </div>

          {forecastError && (
            <p className="error-message">{forecastError}</p>
          )}

          {hours.length > 0 && (
            <>
              <div className="chart-wrap">
                <svg
                  viewBox="0 0 100 100"
                  preserveAspectRatio="none"
                  role="img"
                  aria-label="Графік температури"
                >
                  <polyline
                    points={chartPoints}
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    vectorEffect="non-scaling-stroke"
                  />
                </svg>
              </div>

              <div className="hourly-list">
                {hours.map((item) => (
                  <div className="hour-item" key={item.dt}>
                    <span>
                      {new Date(item.dt * 1000).toLocaleTimeString(
                        "uk-UA",
                        { hour: "2-digit", minute: "2-digit" }
                      )}
                    </span>
                    <img
                      src={`https://openweathermap.org/img/wn/${item.weather[0].icon}.png`}
                      alt=""
                    />
                    <strong>{Math.round(item.main.temp)}°</strong>
                  </div>
                ))}
              </div>
            </>
          )}

          <div className="forecast-heading weekly-heading">
            <h3>Прогноз на 7 днів</h3>
            <button
              className="outline-button"
              onClick={() => setWeekly((value) => !value)}
            >
              {weekly ? "Сховати" : "Показати прогноз"}
            </button>
          </div>

          {weekly && (
            <div className="weekly-list">
              {days.map((item) => (
                <div className="day-item" key={item.dt}>
                  <span>
                    {new Date(item.dt * 1000).toLocaleDateString(
                      "uk-UA",
                      { weekday: "short", day: "numeric", month: "short" }
                    )}
                  </span>
                  <img
                    src={`https://openweathermap.org/img/wn/${item.weather[0].icon}.png`}
                    alt=""
                  />
                  <span>{item.weather[0].description}</span>
                  <strong>{Math.round(item.main.temp)}°</strong>
                </div>
              ))}
              <p className="forecast-note">
                Безкоштовний прогноз API доступний приблизно на 5 днів
                з інтервалом 3 години. Для повних 7 днів потрібен інший
                тариф або погодний сервіс.
              </p>
            </div>
          )}
        </div>
      )}
    </section>
  );
}

export default Weather;
